"""Validation of raw order lines. The limits come from the table in the Item docstring."""
import re

from .models import Item

_LINE = re.compile(r"^\s+(\w+): (str|int), (\d+)\.\.(\d+)\s*$")


def _parse(doc):
    rules = {}
    for line in doc.splitlines():
        match = _LINE.match(line)
        if match:
            name, kind, low, high = match.groups()
            rules[name] = (kind, int(low), int(high))
    return rules


RULES = _parse(Item.__doc__)


def validate_item(data):
    """Return a list of problems, each 'field: reason'. Empty means valid."""
    problems = []
    for name, (kind, low, high) in RULES.items():
        if name not in data:
            problems.append(f"{name}: missing")
            continue
        value = data[name]
        if kind == "str":
            if not isinstance(value, str):
                problems.append(f"{name}: not a string")
            elif not low <= len(value) <= high:
                problems.append(f"{name}: length out of range {low}..{high}")
        elif isinstance(value, bool) or not isinstance(value, int):
            problems.append(f"{name}: not an integer")
        elif not low <= value <= high:
            problems.append(f"{name}: out of range {low}..{high}")
    return problems
MAX_TOTAL_G = 2**31 - 1  # the carrier system stores grams in a signed 32-bit column


def check_total_g(grams):
    if grams > MAX_TOTAL_G:
        raise OverflowError("total weight exceeds the carrier limit")
    return grams
MAX_PARCEL_G = 20000


class Parcel:
    def __init__(self, weight_g, skus):
        self.weight_g = weight_g
        self.skus = list(skus)

    def add(self, weight_g, sku):
        self.weight_g += weight_g
        self.skus.append(sku)


def split_parcels(order):
    """First-fit decreasing. A unit heavier than the limit travels alone."""
    units = []
    for item in order.items:
        units.extend((item.weight_g, item.sku) for _ in range(item.qty))
    units.sort(key=lambda unit: (-unit[0], unit[1]))
    parcels = []
    for grams, sku in units:
        for parcel in parcels:
            if parcel.weight_g + grams <= MAX_PARCEL_G:
                parcel.add(grams, sku)
                break
        else:
            parcels.append(Parcel(grams, [sku]))
    return parcels
ZONES = {"eu": (400, 90), "us": (900, 150), "world": (1500, 260)}  # (base cents, cents per extra step)
STEP_G = 500
HEAVY_G = 10000
HEAVY_SURCHARGE = 500


def shipping_cents(weight_g, zone):
    try:
        base, per_step = ZONES[zone]
    except KeyError:
        raise ValueError(f"unknown zone: {zone!r}") from None
    steps = max(1, -(-weight_g // STEP_G))
    cents = base + per_step * (steps - 1)
    if weight_g > HEAVY_G:
        cents += HEAVY_SURCHARGE
    return cents
"""Freight pricing by weight."""
from .units import half_even_div, to_grams


def freight_cents(weight_g, cents_per_kg):
    """Freight in cents: the weight times the per-kilogram rate, rounded half to even.

    >>> freight_cents(125, 100)
    12
    >>> freight_cents(375, 100)
    38
    >>> freight_cents(2000, 350)
    700
    """
    to_grams(weight_g)
    if isinstance(cents_per_kg, bool) or not isinstance(cents_per_kg, int) or cents_per_kg < 0:
        raise ValueError(f"invalid rate: {cents_per_kg!r}")
    return half_even_div(weight_g * cents_per_kg, 1000)
"""Pallet planning. A pallet carries at most PALLET_G grams."""
from .calc import order_weight_g
from .units import half_even_div

PALLET_G = 500000


def pallet_count(order):
    """Pallets needed for the whole order; none for an empty order.

    >>> from shipcalc.models import Item, Order
    >>> pallet_count(Order([Item("A", 500000)]))
    1
    >>> pallet_count(Order([Item("A", 500001)]))
    2
    """
    return -(-order_weight_g(order) // PALLET_G)


def fill_percent(order):
    """How full the pallets are, in whole percent (half to even); 0 for an empty order.

    >>> from shipcalc.models import Item, Order
    >>> fill_percent(Order([Item("A", 250000)]))
    50
    """
    count = pallet_count(order)
    if count == 0:
        return 0
    return half_even_div(order_weight_g(order) * 100, count * PALLET_G)
LIGHT_G = 500
MEDIUM_G = 2000


def average_weight_g(order):
    """Average weight of one unit in the order.

    >>> from shipcalc.models import Item, Order
    >>> average_weight_g(Order([Item("A", 1000), Item("B", 2000, 2)]))
    1666
    """
    units = sum(item.qty for item in order.items)
    if units == 0:
        return 0
    return sum(item.line_weight_g() for item in order.items) // units


def heaviest(order, n=3):
    return sorted(order.items, key=lambda item: (-item.weight_g, item.sku))[:n]


def weight_bands(order):
    bands = {"light": 0, "medium": 0, "heavy": 0}
    for item in order.items:
        if item.weight_g <= LIGHT_G:
            bands["light"] += item.qty
        elif item.weight_g <= MEDIUM_G:
            bands["medium"] += item.qty
        else:
            bands["heavy"] += item.qty
    return bands
def format_weight(grams):
    """Text form of a weight.

    >>> format_weight(250)
    '250 g'
    >>> format_weight(12000)
    '12.0 kg'
    """
    if grams >= 1000:
        return f"{grams / 1000:.1f} kg"
    return f"{grams} g"


def format_table(order):
    rows = [f"{item.sku:<12}{format_weight(item.weight_g):>12}  x{item.qty}" for item in order.items]
    return "\n".join(rows)
"""Shipping labels for order lines."""
from .format import format_weight

LIFT_G = 25000


def lift_notice(item):
    """Two people must lift a unit that is heavier than 25 kg.

    >>> from shipcalc.models import Item
    >>> lift_notice(Item("A", 25000))
    ''
    >>> lift_notice(Item("A", 25001))
    '2-PERSON LIFT'
    """
    return "2-PERSON LIFT" if item.weight_g > LIFT_G else ""


def label(item):
    text = f"{item.sku} {format_weight(item.weight_g)} x{item.qty}"
    notice = lift_notice(item)
    return f"{text} {notice}" if notice else text


def render(order):
    return "\n".join(label(item) for item in order.items)
"""Weight band surcharges, read from the generated table data/surcharges.json."""
import json
from pathlib import Path

from .units import to_grams

DEFAULT_TABLE = Path(__file__).with_name("data") / "surcharges.json"


def load(path=None):
    with open(path or DEFAULT_TABLE, encoding="utf-8") as handle:
        data = json.load(handle)
    if data.get("schema") != 1:
        raise ValueError(f"unsupported schema: {data.get('schema')!r}")
    bands = [{"max_g": to_grams(band["max_g"]), "cents": band["cents"]} for band in data["bands"]]
    bands.sort(key=lambda band: band["max_g"])
    return {"bands": bands, "over_cents": data["over_cents"]}


def cents_for(weight_g, table=None):
    """Surcharge of the first band whose limit is at least the weight; else the over-limit surcharge."""
    table = load() if table is None else table
    for band in table["bands"]:
        if weight_g <= band["max_g"]:
            return band["cents"]
    return table["over_cents"]
"""Tare handling: net weight from a gross weight."""
from .units import half_even_div, to_grams


def net_weight_g(gross_g, tare_g):
    if to_grams(tare_g) > to_grams(gross_g):
        raise ValueError("tare exceeds gross weight")
    return gross_g - tare_g


def tare_for_percent_g(gross_g, percent):
    """The tare that is `percent` percent of the gross weight, half to even.

    >>> tare_for_percent_g(10005, 10)
    1000
    >>> tare_for_percent_g(10015, 10)
    1002
    """
    to_grams(gross_g)
    if isinstance(percent, bool) or not isinstance(percent, int) or not 0 <= percent <= 100:
        raise ValueError(f"invalid percent: {percent!r}")
    return half_even_div(gross_g * percent, 100)


def net_after_percent_g(gross_g, percent):
    return gross_g - tare_for_percent_g(gross_g, percent)
"""Weighbridge check: is the measured weight close enough to the declared one?"""
from .units import half_even_div, to_grams

MIN_ALLOWANCE_G = 20
ALLOWANCE_PERCENT = 2


def allowance_g(declared_g):
    """The larger of 20 g and 2 percent of the declared weight (half to even).

    >>> allowance_g(1000)
    20
    >>> allowance_g(10075)
    202
    """
    return max(MIN_ALLOWANCE_G, half_even_div(to_grams(declared_g) * ALLOWANCE_PERCENT, 100))


def deviation_g(declared_g, measured_g):
    return abs(to_grams(declared_g) - to_grams(measured_g))


def within_tolerance(declared_g, measured_g):
    """
    >>> within_tolerance(1000, 1020)
    True
    >>> within_tolerance(1000, 1021)
    False
    """
    return deviation_g(declared_g, measured_g) <= allowance_g(declared_g)
import json

from .models import Item, Order


def save(order, path):
    data = {"schema": 1, "items": [item.to_dict() for item in order.items]}
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(data, handle, indent=2, sort_keys=True)
        handle.write("\n")


def load(path):
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
    if data.get("schema") != 1:
        raise ValueError(f"unsupported schema: {data.get('schema')!r}")
    return Order(Item.from_dict(raw) for raw in data["items"])
"""Audit log: one JSON object per line. See docs/FORMATS.md."""
import json

from .units import to_grams


def write_entry(path, event, sku, weight_g, qty=1):
    to_grams(weight_g)
    entry = {"v": 1, "event": event, "sku": sku, "weight_g": weight_g, "qty": qty}
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(json.dumps(entry, sort_keys=True) + "\n")


def read_entries(path):
    entries = []
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            entry = json.loads(line)
            version = entry.get("v", 1)
            if isinstance(version, bool) or version != 1:
                raise ValueError(f"unsupported log version: {version!r}")
            if "weight_g" in entry:
                to_grams(entry["weight_g"])
            entries.append(entry)
    return entries


def total_added_g(path):
    return sum(e["weight_g"] * e.get("qty", 1) for e in read_entries(path) if e.get("event") == "add" and "weight_g" in e)
"""CSV import. See docs/FORMATS.md."""
import re

from .models import Item, Order

COLUMNS = ("sku", "weight_g", "qty")
_DIGITS = re.compile(r"[0-9]+")


def parse_csv(text):
    lines = text.splitlines()
    if not lines or not lines[0]:
        raise ValueError("empty file")
    names = [cell.strip() for cell in lines[0].split(",")]
    for name in names:
        if name not in COLUMNS:
            raise ValueError(f"unknown column: {name!r}")
    for name in COLUMNS[:2]:
        if name not in names:
            raise ValueError(f"missing column: {name!r}")
    order = Order()
    for number, line in enumerate(lines[1:], start=2):
        if not line:
            continue
        cells = line.split(",")
        if len(cells) != len(names):
            raise ValueError(f"row {number}: wrong number of cells")
        row = dict(zip(names, cells))
        if not _DIGITS.fullmatch(row["weight_g"]):
            raise ValueError(f"invalid weight: {row['weight_g']!r}")
        qty = row.get("qty", "1")
        if not _DIGITS.fullmatch(qty) or int(qty) < 1:
            raise ValueError(f"invalid quantity: {qty!r}")
        order.add(Item(row["sku"], int(row["weight_g"]), int(qty)))
    return order
from .calc import order_weight_g
from .packing import split_parcels


def to_csv(order):
    lines = ["sku,weight_g,qty"]
    for item in order.items:
        lines.append(f"{item.sku},{item.weight_g},{item.qty}")
    return "\n".join(lines) + "\n"


def carrier_payload(order):
    return {"weight_g": order_weight_g(order), "parcels": len(split_parcels(order))}


def edi_segment(order):
    return f"WGT*G*{order_weight_g(order)}~"


def barcode(order):
    return f"WT{order_weight_g(order):010d}"
from .calc import order_weight_g, quote

_STORE = {}


def quote_key(order, zone):
    return f"quote:{zone}:{order_weight_g(order)}:{len(order.items)}"


def cached_quote(order, zone):
    key = quote_key(order, zone)
    if key not in _STORE:
        _STORE[key] = quote(order, zone)
    return _STORE[key]


def clear():
    _STORE.clear()
import sys

from . import storage
from .calc import order_weight_g, quote
from .export import to_csv
from .format import format_table, format_weight
from .importer import parse_csv
from .models import Item

USAGE = """usage: python -m shipcalc show ORDER_JSON
       python -m shipcalc add ORDER_JSON SKU WEIGHT_G QTY
       python -m shipcalc quote ORDER_JSON --zone ZONE
       python -m shipcalc export ORDER_JSON
       python -m shipcalc import ORDER_JSON CSV_FILE
"""


def _show(order):
    print(format_table(order))
    print(f"total weight: {format_weight(order_weight_g(order))}")


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        if len(args) == 2 and args[0] == "show":
            _show(storage.load(args[1]))
        elif len(args) == 5 and args[0] == "add":
            order = storage.load(args[1])
            order.add(Item(args[2], int(args[3]), int(args[4])))
            storage.save(order, args[1])
        elif len(args) == 4 and args[0] == "quote" and args[2] == "--zone":
            order = storage.load(args[1])
            result = quote(order, args[3])
            print(f"items: {len(order.items)}")
            print(f"total weight: {format_weight(result['weight_g'])}")
            print(f"parcels: {result['parcels']}")
            print(f"shipping: {result['cents'] // 100}.{result['cents'] % 100:02d} EUR")
        elif len(args) == 2 and args[0] == "export":
            sys.stdout.write(to_csv(storage.load(args[1])))
        elif len(args) == 3 and args[0] == "import":
            order = storage.load(args[1])
            with open(args[2], encoding="utf-8") as handle:
                imported = parse_csv(handle.read())
            for item in imported.items:
                order.add(item)
            storage.save(order, args[1])
        else:
            sys.stderr.write(USAGE)
            return 2
    except (ValueError, OverflowError) as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 2
    return 0
"""Demo orders shipped with the package (fixtures/*.json)."""
from pathlib import Path

from . import storage

FIXTURES = Path(__file__).with_name("fixtures")


def names():
    return sorted(path.stem for path in FIXTURES.glob("*.json"))


def load_demo(name):
    if name not in names():
        raise ValueError(f"unknown demo: {name!r}")
    return storage.load(FIXTURES / f"{name}.json")
"""Plugin registry: the extras listed in plugins.json are loaded by their dotted module name."""
import importlib
import json
from pathlib import Path

DEFAULT_CONFIG = Path(__file__).with_name("plugins.json")


def load(path=None):
    with open(path or DEFAULT_CONFIG, encoding="utf-8") as handle:
        data = json.load(handle)
    if data.get("schema") != 1:
        raise ValueError(f"unsupported schema: {data.get('schema')!r}")
    return [importlib.import_module(entry["module"]).make(dict(entry.get("options", {}))) for entry in data["plugins"]]


def extras_cents(order, plugins=None):
    plugins = load() if plugins is None else plugins
    return sum(plugin.surcharge_cents(order) for plugin in plugins)
"""Generates data/surcharges.json. Run: python -m shipcalc.gen_surcharges"""
import json

from .surcharges import DEFAULT_TABLE

BANDS_G = [(1000, 0), (5000, 150), (15000, 400)]
OVER_CENTS = 900


def build_table():
    return {
        "schema": 1,
        "bands": [{"max_g": grams, "cents": cents} for grams, cents in BANDS_G],
        "over_cents": OVER_CENTS,
    }


def render():
    return json.dumps(build_table(), indent=2, sort_keys=True) + "\n"


def main():
    DEFAULT_TABLE.write_text(render(), encoding="utf-8")


if __name__ == "__main__":
    main()
"""Surcharge per heavy parcel. Options: parcel_over_<unit>, cents."""
from ..packing import split_parcels

UNIT = "g"


class Bulky:
    def __init__(self, over, cents):
        self.over = over
        self.cents = cents

    def surcharge_cents(self, order):
        heavy = [p for p in split_parcels(order) if getattr(p, "weight_" + UNIT) > self.over]
        return len(heavy) * self.cents


def make(options):
    return Bulky(options["parcel_over_" + UNIT], options["cents"])
"""Surcharge per light (fragile) unit. Options: max_unit_<unit>, cents."""
UNIT = "g"


class Fragile:
    def __init__(self, max_unit, cents):
        self.max_unit = max_unit
        self.cents = cents

    def surcharge_cents(self, order):
        count = sum(item.qty for item in order.items if getattr(item, "weight_" + UNIT) <= self.max_unit)
        return count * self.cents


def make(options):
    return Fragile(options["max_unit_" + UNIT], options["cents"])
"""Insurance per started step of total weight, from a minimum total on. Options: step_<unit>, min_total_<unit>, cents_per_step."""
from .. import calc

UNIT = "g"


class Insurance:
    def __init__(self, step, min_total, cents_per_step):
        self.step = step
        self.min_total = min_total
        self.cents_per_step = cents_per_step

    def surcharge_cents(self, order):
        total = getattr(calc, "order_weight_" + UNIT)(order)
        if total < self.min_total:
            return 0
        return -(-total // self.step) * self.cents_per_step


def make(options):
    return Insurance(options["step_" + UNIT], options["min_total_" + UNIT], options["cents_per_step"])

