"""Insurance per started step of total weight, from a minimum total on.

Options: step_<unit>, min_total_<unit>, cents_per_step (weights are kilogram strings).
"""
from .. import calc
from ..units import kg_to_g

UNIT = "kg"


class Insurance:
    def __init__(self, step, min_total, cents_per_step):
        self.step = step
        self.min_total = min_total
        self.cents_per_step = cents_per_step

    def surcharge_cents(self, order):
        total = kg_to_g(getattr(calc, "order_weight_" + UNIT)(order))
        if total < kg_to_g(self.min_total):
            return 0
        return -(-total // kg_to_g(self.step)) * self.cents_per_step


def make(options):
    return Insurance(options["step_" + UNIT], options["min_total_" + UNIT], options["cents_per_step"])

